import{H as e,at as t,ot as n,yt as r}from"./chunks/framework.C56o9mkq.js";var i=JSON.parse(`{"title":"CV安监项目集合","description":"nxu-tech 组织全部公开 CV 算法 SDK 与行业方案","frontmatter":{"layout":"doc","title":"CV安监项目集合","description":"nxu-tech 组织全部公开 CV 算法 SDK 与行业方案","categories":["专栏","nxu-tech"],"tags":["计算机视觉","YOLOv8","nxu-tech"],"lastUpdated":true,"sidebar":true},"headers":[],"relativePath":"专栏/nxu-tech/index.md","filePath":"专栏/nxu-tech/index.md","lastUpdated":1787585500000}`),a={name:`专栏/nxu-tech/index.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="cv安监项目集合" tabindex="-1">CV安监项目集合 <a class="header-anchor" href="#cv安监项目集合" aria-label="Permalink to “CV安监项目集合”">​</a></h1><p>基于 <a href="https://github.com/nxu-tech" target="_blank" rel="noreferrer">nxu-tech</a> 组织的 <strong>23</strong> 个公开仓库，涵盖 YOLOv8 目标检测/分割 SDK 与政企垂直场景算法。</p><h3 id="基础框架" tabindex="-1">基础框架 <a class="header-anchor" href="#基础框架" aria-label="Permalink to “基础框架”">​</a></h3><ul><li><a href="./nxu_det_yolov8_trt/">YOLOv8 目标检测 (TensorRT)</a> — 基于 TensorRT 的 YOLOv8 目标检测 SDK，支持 GPU 加速推理与动态库交付。</li><li><a href="./nxu_det_yolov8_ort/">YOLOv8 目标检测 (ONNXRuntime)</a> — 基于 ONNX Runtime 的 YOLOv8 目标检测 SDK，适配 CPU/GPU 多种部署环境。</li><li><a href="./nxu_seg_yolov8_trt/">YOLOv8 实例分割 (TensorRT)</a> — 基于 TensorRT 的 YOLOv8 实例分割 SDK。</li><li><a href="./nxu_utils/">nxu_utils 工具库</a> — nxu-tech 算法库公共依赖，封装常用图像与推理辅助函数。</li><li><a href="./gpu_utils/">GPU 信息工具</a> — Windows 与 Ubuntu 下获取 GPU 信息的实用工具。</li></ul><h3 id="明厨亮灶" tabindex="-1">明厨亮灶 <a class="header-anchor" href="#明厨亮灶" aria-label="Permalink to “明厨亮灶”">​</a></h3><ul><li><a href="./nxu_kmd/">明厨亮灶 · 老鼠检测</a> — 明厨亮灶场景下的老鼠检测算法库。</li><li><a href="./nxu_khd/">明厨亮灶 · 未戴厨帽检测</a> — 检测厨房工作人员是否按规定佩戴厨帽。</li><li><a href="./nxu_kcd/">明厨亮灶 · 打电话检测</a> — 检测厨房区域内人员打电话行为。</li><li><a href="./nxu_nwm/">明厨亮灶 · 未戴口罩检测</a> — 检测厨房工作人员是否正确佩戴口罩。</li></ul><h3 id="环保城管" tabindex="-1">环保城管 <a class="header-anchor" href="#环保城管" aria-label="Permalink to “环保城管”">​</a></h3><ul><li><a href="./nxu_fsd/">烟火检测</a> — 烟火/明火检测算法，适用于安防与消防预警。</li><li><a href="./nxu_dfd/">扬尘检测</a> — 工地与道路扬尘检测算法。</li><li><a href="./nxu_swd/">垃圾固废检测</a> — 垃圾与固体废弃物堆放检测。</li><li><a href="./nxu_ied/">排污检测</a> — 环保领域排污行为检测算法。</li><li><a href="./nxu_bsd/">裸土覆网检测</a> — 裸土是否按规定覆网的检测算法。</li></ul><h3 id="交通安防" tabindex="-1">交通安防 <a class="header-anchor" href="#交通安防" aria-label="Permalink to “交通安防”">​</a></h3><ul><li><a href="./nxu_gvd/">通用车辆检测</a> — 小汽车、摩托车、公交、SUV、皮卡、MPV、三轮车、货车、面包车等多类型车辆检测。</li><li><a href="./nxu_evd/">工程车辆检测</a> — 工程车辆（渣土车、挖掘机等）检测算法。</li><li><a href="./nxu_wsh/">未戴头盔检测</a> — 骑行/作业人员未佩戴头盔检测。</li><li><a href="./nxu_ksd/">抽烟检测</a> — 人员抽烟行为检测算法。</li><li><a href="./nxu_pid/">行人检测</a> — 通用行人检测算法。</li></ul><h3 id="行业方案" tabindex="-1">行业方案 <a class="header-anchor" href="#行业方案" aria-label="Permalink to “行业方案”">​</a></h3><ul><li><a href="./nxu_sln_mcso/">无人机巡河方案</a> — 无人机巡河：非法采矿、非法建设、非法堆放、非法占用检测。</li><li><a href="./nxu_ssm/">游泳安全检测</a> — 游泳安全检测与目标跟踪。</li><li><a href="./nxu_aed/">动物检测</a> — 猫、狗、牛、羊等常见动物检测。</li><li><a href="./nxu_tad/">藏羚羊检测</a> — 藏羚羊目标检测算法。</li></ul><hr><p><a href="./../">← 返回专栏</a></p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};